 raise ValueError("grid cannot be empty")
 first_len = len(grid[0])
 for row in grid:
 if len(row) != first_len:
 raise ValueError("rows are not all the same length")
 # Validate characters
 for row in grid:
 for ch in row:
 if ch not in 'S E # .':
 raise ValueError(f"invalid character '{ch}'")
 # Count S and E
 s_count = sum(1 for row in grid for ch in row if ch == 'S')
 e_count = sum(1 for row in grid for ch in row if ch == 'E')
 if s_count != 1 or e_count != 1:
 raise ValueError("not exactly one 'S' and one 'E'")
 # Find start and end
 rows = len(grid)
 cols = len(grid[0])
 start = None
 end = None
 for i, row in enumerate(grid):
 for j, ch in enumerate(row):
 if ch == 'S':
 start = (i, j)
 elif ch == 'E':
 end = (i, j)
 # BFS
 visited = set()
 queue = deque()
 queue.append((start[0], start[1], 0))
 visited.add(start)
 directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
 while queue:
 r, c, dist = queue.popleft()
 if (r, c) == end:
 return dist
 for dr, dc in directions:
 nr, nc = r + dr, c + dc
 if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited:
 visited.add((nr, nc))
 queue.append((nr, nc, dist + 1))
 return -1
